    DepartmentID INT NOT NULL PRIMARY KEY,
    Name NVARCHAR(50) NOT NULL
);

CREATE TABLE dbo.Employee (
    EmployeeID INT NOT NULL PRIMARY KEY,
    DepartmentID INT NOT NULL
        REFERENCES dbo.Department (DepartmentID)
);

